import * as React from "react";
import { StyleSheet, View } from "react-native";
import Svg, { Circle, Path } from "react-native-svg";
import { LinearGradient } from "expo-linear-gradient";
import Animated, { Easing, interpolate, useAnimatedProps, useAnimatedStyle, useSharedValue, withDelay, withRepeat, withTiming, Extrapolation, type SharedValue } from "react-native-reanimated";
import { lift, palette, useTheme } from "../theme";
import { Burst, useOnce } from "./motion";
// The mark's geometry, shared with the web app (generated by scripts/brand-assets.mts).
import { MARK } from "../../../src/lib/brand/mark";

const AnimatedPath = Animated.createAnimatedComponent(Path);

/**
 * The mark (Focus): two open rings closing in on one coral point, the
 * estimate. The outer ring lighter, the inner one stronger.
 */
export function Mark({ size = 28, color, dot = palette.coral }: { size?: number; color?: string; dot?: string }) {
  const { c } = useTheme();
  const stroke = color ?? c.text;
  return (
    <Svg width={size} height={size} viewBox="0 0 64 64" accessibilityElementsHidden importantForAccessibility="no-hide-descendants">
      {[MARK.outer, MARK.inner].map((g) => (
        <Path key={g.r} d={g.d} fill="none" stroke={stroke} strokeWidth={g.w} strokeOpacity={g.opacity} strokeLinecap="round" />
      ))}
      <Circle cx={MARK.cx} cy={MARK.cy} r={MARK.dot.r} fill={dot} />
    </Svg>
  );
}

/** The app symbol: the white rings on a squircle tile, violet turning to navy, the point in coral. */
export function Symbol({ size = 40 }: { size?: number }) {
  const { c } = useTheme();
  const radius = size * 0.3;
  return (
    <View style={[{ width: size, height: size, borderRadius: radius, backgroundColor: palette.logoTo, alignItems: "center", justifyContent: "center" }, lift("glow", c, palette.logoFrom)]}>
      <View pointerEvents="none" style={[StyleSheet.absoluteFill, { borderRadius: radius, overflow: "hidden" }]}>
        <LinearGradient colors={[palette.logoFrom, palette.logoTo]} start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }} style={StyleSheet.absoluteFill} />
      </View>
      {/* In a View: on the web a bare <svg> would paint under the absolutely placed gradient. */}
      <View>
        <Mark size={size * 0.74} color={palette.white} />
      </View>
    </View>
  );
}

function Ring({ ring, t, from, to, color }: { ring: (typeof MARK)["outer"]; t: SharedValue<number>; from: number; to: number; color: string }) {
  const props = useAnimatedProps(() => ({ strokeDashoffset: interpolate(t.value, [from, to], [ring.length, 0], Extrapolation.CLAMP) }));
  return (
    <AnimatedPath d={ring.d} fill="none" stroke={color} strokeWidth={ring.w} strokeOpacity={ring.opacity} strokeLinecap="round" strokeDasharray={`${ring.length}`} animatedProps={props} />
  );
}

/**
 * The mark, alive: the rings draw in, outside first, then the coral point
 * lands. The loading state while a scene is prepared (looping: it draws,
 * rests and draws again) and the signature on the briefing and complete
 * screens (once). Still under reduced motion. Lavender-violet on the canvas;
 * white on the highlight card.
 *
 * Played once with `burst`, the point pops as it lands: a ring and a few
 * coral particles, about a second (none under reduced motion). `onLand` fires
 * at that moment (at once when still).
 */
export function MarkLive({ width = 120, loop = true, color, onHero, burst, onLand }: { width?: number; loop?: boolean; color?: string; onHero?: boolean; burst?: boolean; onLand?: () => void }) {
  const { c, reduceMotion } = useTheme();
  const t = useSharedValue(reduceMotion ? 1 : 0);
  const stroke = color ?? (onHero ? "#FFFFFF" : c.accentText);
  const dot = onHero ? palette.coral : c.signal;
  const size = width;

  React.useEffect(() => {
    if (reduceMotion) {
      t.value = 1;
      return;
    }
    t.value = 0;
    const run = withTiming(1, { duration: 1500, easing: Easing.out(Easing.cubic) });
    t.value = loop ? withRepeat(withDelay(500, run), -1, false) : withDelay(200, run);
  }, [loop, reduceMotion, t]);

  // The outer ring draws first, the inner one overlaps it, then the point lands.
  const dotStyle = useAnimatedStyle(() => {
    const k = interpolate(t.value, [0.66, 0.9], [0, 1], Extrapolation.CLAMP);
    const s = k < 0.7 ? interpolate(k, [0, 0.7], [0, 1.25]) : interpolate(k, [0.7, 1], [1.25, 1]);
    return { transform: [{ scale: s }], opacity: k > 0 ? 1 : 0 };
  });

  const pop = useSharedValue(0);
  const land = React.useCallback(() => {
    if (burst && !reduceMotion) pop.value = withTiming(1, { duration: 1000, easing: Easing.out(Easing.quad) });
    onLand?.();
  }, [burst, reduceMotion, onLand, pop]);
  useOnce(() => {
    "worklet";
    return !loop && t.value >= 0.83;
  }, land);

  const unit = size / 64;
  const point = MARK.dot.r * 2 * unit;
  return (
    <View style={{ width: size, height: size }} accessibilityElementsHidden importantForAccessibility="no-hide-descendants">
      <Svg width={size} height={size} viewBox="0 0 64 64">
        <Ring ring={MARK.outer} t={t} from={0} to={0.55} color={stroke} />
        <Ring ring={MARK.inner} t={t} from={0.2} to={0.7} color={stroke} />
      </Svg>
      <View style={{ position: "absolute", left: MARK.cx * unit - point / 2, top: MARK.cy * unit - point / 2, width: point, height: point }}>
        {burst && !reduceMotion ? <Burst t={pop} size={point} color={dot} /> : null}
        <Animated.View style={[{ width: point, height: point, borderRadius: point / 2, backgroundColor: dot }, dotStyle]} />
      </View>
    </View>
  );
}
